//! The Rust text of the table: each entry's geometry as `Debug` prints
//! it, which is the constructor expression.

use std::fmt::Write;

use vapors_shapes::{Geometry, RuntimeShape, TABLE_FORMAT};

/// `shapes.rs`: `SHAPES`, one entry per shape.
pub(super) fn table(entries: &[RuntimeShape]) -> String {
    let mut text = format!(
        "// Generated by vapors-compiler from the .wisp files; edit those, not this file.\n\n/// This crate's literal shapes, each once (docs/plans/one-scene.md 1.3).\n#[allow(clippy::unreadable_literal, clippy::approx_constant, reason = \"f32 numbers as printed, not written by hand\")]\npub static SHAPES: vapors_shapes::ShapeTable = {{\n    use vapors_shapes::{{Geometry, MeshCorner, MeshTriangle, ShapeEntry, ShapeTable}};\n    ShapeTable::new(env!(\"CARGO_PKG_NAME\"), {TABLE_FORMAT}, &[\n"
    );
    for shape in entries {
        let canonical = shape.canonical();
        let _ = writeln!(
            text,
            "        ShapeEntry {{\n            site: {:?},\n            canonical: &{:?},\n            hash: {:#x},\n            geometry: {},\n        }},",
            shape.site(),
            canonical.bytes(),
            canonical.hash(),
            geometry(&shape.geometry())
        );
    }
    text.push_str("    ])\n};\n");
    text
}

fn geometry(geometry: &Geometry<'_>) -> String {
    match geometry {
        Geometry::Mesh { triangles } => format!("Geometry::Mesh {{ triangles: &{triangles:?} }}"),
        closed => format!("Geometry::{closed:?}"),
    }
}
